import re

def parse_duration(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    stripped = text.strip()
    if not stripped:
        raise ValueError("empty duration")

    parts = re.findall(r'(\d+)([dhms])', stripped)
    if not parts:
        raise ValueError("no valid parts found")

    # ensure the whole string is consumed (only digits, units and spaces)
    reconstructed = ''.join(f'{n}{u}' for n, u in parts)
    if re.sub(r'\s+', '', stripped) != reconstructed:
        raise ValueError("invalid characters in duration")

    # each unit at most once
    seen = set()
    total = 0
    multipliers = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    for num, unit in parts:
        if unit in seen:
            raise ValueError(f"duplicate unit {unit}")
        seen.add(unit)
        total += int(num) * multipliers[unit]

    return total
```

