def common_path_prefix(paths: list[str]) -> str:
    if not paths:
        return ""

    # Normalize paths: remove repeated slashes and trailing slashes
    normalized = []
    for p in paths:
        parts = [part for part in p.split('/') if part]
        normalized.append('/' + '/'.join(parts) if parts else '/')

    # Split into components, skipping the leading empty string from absolute paths
    components = [p.split('/')[1:] for p in normalized]

    common = components[0]
    for comp in components[1:]:
        length = min(len(common), len(comp))
        new_common = []
        for i in range(length):
            if common[i] == comp[i]:
                new_common.append(common[i])
            else:
                break
        common = new_common
        if not common:
            break

    return "/" + "/".join(common) if common else ""
