def common_path_prefix(paths: list[str]) -> str:
    if not paths:
        return ""

    # Normalize each path: split into components, ignoring empty parts from repeated slashes
    normalized = []
    for p in paths:
        # Remove trailing slash (except root) and split by '/'
        parts = [part for part in p.split('/') if part]
        normalized.append(parts)

    # Find common prefix components
    common = []
    for comps in zip(*normalized):
        if all(c == comps[0] for c in comps):
            common.append(comps[0])
        else:
            break

    # Build result
    if not common:
        return "/"
    result = "/" + "/".join(common)
    return result
