    for parts in split_paths[1:]:
        new_common = []
        for a, b in zip(common, parts):
            if a != b:
                break
            new_common.append(a)
        common = new_common
        if not common:
            return ""

    result = "/".join(common)
    if not result.startswith("/"):
        result = "/" + result
    return result if result else "/"
