import re

def parse_duration(text: str) -> int:
    if not isinstance(text, str):
        raise ValueError
    stripped = text.strip()
    if not stripped:
        raise ValueError

    # allow spaces only between parts, never between number and unit
    if not re.fullmatch(r'(?:\d+[dhms]\s*)+', stripped):
        raise ValueError

    matches = re.findall(r'(\d+)([dhms])', stripped)
    if not matches:
        raise ValueError

    units_seen = set()
    total = 0
    mapping = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    for num_str, unit in matches:
        if unit in units_seen:
            raise ValueError("each unit may appear at most once")
        units_seen.add(unit)
        total += int(num_str) * mapping[unit]

    return total
