    for i in range(min_len):
        part = comps_list[0][i]
        if all(c[i] == part for c in comps_list):
            common.append(part)
        else:
            break

    if not common:
        # all paths are absolute, root is the common prefix
        return "/"
    return "/" + "/".join(common)
