    # spaces between parts. No leading/trailing spaces or other characters.
    if re.fullmatch(r"(?:\d+[dhms])(?:\s*\d+[dhms])*", text) is None:
        raise ValueError("invalid duration format")

    parts = re.findall(r"(\d+)([dhms])", text)
    seen_units = set()
    total_seconds = 0

    for number, unit in parts:
        if unit in seen_units:
            raise ValueError("duplicate duration unit")
        seen_units.add(unit)
        total_seconds += int(number) * _UNIT_SECONDS[unit]

    return total_seconds
