def common_path_prefix(paths: list[str]) -> str:
    """Return the longest leading path shared by all the given absolute Unix paths."""
    if not paths:
        return ""

    normalized = []
    for p in paths:
        # split on '/', drop empty parts to handle // and trailing /
        parts = [seg for seg in p.split('/') if seg]
        normalized.append(parts)

    # find common component prefix
    min_len = min(len(p) for p in normalized)
    common = []
    for i in range(min_len):
        comp = normalized[0][i]
        if all(p[i] == comp for p in normalized):
            common.append(comp)
        else:
            break

    if not common:
        return "/"
    return "/" + "/".join(common)
