import re

def parse_duration(text: str) -> int:
    text = text.strip()
    if not text:
        raise ValueError("Empty string")

    parts = re.findall(r'\d+[dhms]', text)
    if not parts or ''.join(parts) != text.replace(' ', ''):
        raise ValueError("Invalid format")

    total = 0
    seen = set()
    for part in parts:
        num = int(part[:-1])
        unit = part[-1]
        if unit in seen:
            raise ValueError("Duplicate unit")
        seen.add(unit)
        if unit == 'd':
            total += num * 86400
        elif unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total
