    words = text.split()
    if not words:
        return []
    lines = []
    current_line = []
    current_length = 0

    for word in words:
        if len(word) > width:
            # flush current line if any
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_length = 0
            lines.append(word)
        else:
            if current_length == 0:
                current_line.append(word)
                current_length = len(word)
            elif current_length + 1 + len(word) <= width:
                current_line.append(word)
                current_length += 1 + len(word)
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
