def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Empty string")

    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    seen = set()
    total = 0

    parts = text.split()
    for part in parts:
        if not part:
            continue
        # Find the unit at the end
        unit = part[-1]
        if unit not in units:
            raise ValueError(f"Invalid unit: {unit}")
        if unit in seen:
            raise ValueError(f"Duplicate unit: {unit}")
        seen.add(unit)

        num_str = part[:-1]
        if not num_str or not num_str.isdigit():
            raise ValueError(f"Invalid number in part: {part}")
        num = int(num_str)
        total += num * units[unit]

    if not seen:
        raise ValueError("No valid duration parts")

    return total

