def common_path_prefix(paths: list[str]) -> str:
    """Return the longest leading path shared by all the given absolute Unix paths.

    Compare whole path components, not characters: "/a/bc" and "/a/bd"
    share "/a". Treat repeated slashes and a trailing slash as a single
    separator ("/a//b/" is the same as "/a/b"). The result never ends with
    a slash unless it is the root "/". Return "" for an empty list.

    >>> common_path_prefix(["/usr/local/bin", "/usr/local/lib", "/usr/share"])
    '/usr'
    >>> common_path_prefix(["/srv/app1", "/srv/app2"])
    '/srv'
    """
    if not paths:
        return ""

    # Normalize each path: split by '/', remove empty components (due to repeated slashes)
    # and ignore trailing slash (which would create an empty component at the end)
    normalized = []
    for p in paths:
        # Split and filter out empty strings
        parts = [part for part in p.split('/') if part]
        normalized.append(parts)

    # Find the common prefix length by comparing component by component
    common = []
    # Use the first path's components as reference
    first = normalized[0]
    for i, comp in enumerate(first):
        # Check if all paths have this component at position i
        for other in normalized[1:]:
            if i >= len(other) or other[i] != comp:
                # No common component at this position
                if i == 0:
                    return ""  # No common first component (shouldn't happen for absolute paths)
                else:
                    # Return the common prefix found so far
                    return "/" + "/".join(common)
        common.append(comp)

    # If we've processed all components of the first path, all paths match it fully
    # But we need to check if all paths are exactly the same length
    for other in normalized[1:]:
        if len(other) != len(first):
            # The first path is a prefix of others, return the first path
            return "/" + "/".join(common)

    # All paths are identical
    return "/" + "/".join(common)
```

