def parse_duration(text: str) -> int:
    """Convert a duration such as "1h30m" or "2d 4h 15s" to a number of seconds."""
    if not text:
        raise ValueError("Empty string is not a valid duration")

    parts = text.split()
    total_seconds = 0
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    used_units = set()

    for part in parts:
        if not part:
            continue
        # Find the unit character
        unit = part[-1]
        if unit not in units:
            raise ValueError(f"Invalid unit '{unit}' in '{part}'")
        if unit in used_units:
            raise ValueError(f"Unit '{unit}' appears more than once")

        number_str = part[:-1]
        if not number_str or not number_str.isdigit():
            raise ValueError(f"Invalid number in '{part}'")

        number = int(number_str)
        total_seconds += number * units[unit]
        used_units.add(unit)

    if not used_units:
        raise ValueError("No valid duration parts found")

    return total_seconds

