        if nums[i] != nums[i-1] + 1:
            if i - start_idx >= 3:
                result.append(f"{nums[start_idx]}-{nums[i-1]}")
            else:
                result.extend(map(str, nums[start_idx:i]))
            start_idx = i

    if len(nums) - start_idx >= 3:
        result.append(f"{nums[start_idx]}-{nums[-1]}")
    else:
        result.extend(map(str, nums[start_idx:]))

    return ",".join(result)
