    """Return the string representation of integer x in the given base (base < 10)."""
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9 inclusive.")
    if x == 0:
        return "0"
    negative = x < 0
    x = -x if negative else x
    digits = []
    while x > 0:
        digits.append(str(x % base))
        x //= base
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))
