def change_base(x: int, base: int) -> str:
    """Convert integer x to a string representation in the given base (base < 10)."""
    if base < 2:
        raise ValueError("Base must be at least 2")
    if x == 0:
        return "0"
    sign = '-' if x < 0 else ''
    x = abs(x)
    digits = []
    while x:
        digits.append(str(x % base))
        x //= base
    return sign + ''.join(reversed(digits))
