def f(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            # sum from 1 to i
            total = sum(range(1, i + 1))
        else:
            # factorial of i
            fact = 1
            for j in range(1, i + 1):
                fact *= j
            total = fact
        result.append(total)
    return result
