import re

def parse_duration(text: str) -> int:
    """Convert a duration such as "1h30m" or "2d 4h 15s" to a number of seconds."""
    if not isinstance(text, str) or text.strip() == '':
        raise ValueError

    # only digits followed immediately by d/h/m/s, separated by optional whitespace
    if not re.fullmatch(r'\s*(?:\d+[dhms]\s*)+', text):
        raise ValueError

    matches = re.findall(r'(\d+)([dhms])', text)
    if not matches:
        raise ValueError

    units = [u for _, u in matches]
    if len(units) != len(set(units)):
        raise ValueError  # each unit may appear at most once

    mapping = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    for n, u in matches:
        total += int(n) * mapping[u]
    return total
```

