def anti_shuffle(s):
    result = []
    current = []

    for ch in s:
        if ch == ' ':
            if current:
                result.append(''.join(sorted(current)))
                current = []
            result.append(' ')
        else:
            current.append(ch)

    if current:
        result.append(''.join(sorted(current)))

    return ''.join(result)
