def compress_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    unique_nums = sorted(set(nums))
    parts = []
    i = 0

    while i < len(unique_nums):
        start = unique_nums[i]
        j = i

        while j + 1 < len(unique_nums) and unique_nums[j + 1] == unique_nums[j] + 1:
            j += 1

        length = j - i + 1

        if length >= 3:
            parts.append(f"{start}-{unique_nums[j]}")
        else:
            for k in range(i, j + 1):
                parts.append(str(unique_nums[k]))

        i = j + 1

    return ",".join(parts)
```

