import re

def parse_duration(text: str) -> int:
    if not text:
        raise ValueError("Empty duration")

    parts = re.findall(r'\d+[dhms]', text)

    if not parts or ''.join(parts) != text.replace(' ', ''):
        raise ValueError("Invalid format")

    units_seen = set()
    total_seconds = 0
    unit_map = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    for part in parts:
        num_str = part[:-1]
        unit = part[-1]
        if unit in units_seen:
            raise ValueError(f"Duplicate unit: {unit}")
        units_seen.add(unit)
        total_seconds += int(num_str) * unit_map[unit]

    return total_seconds
```

